"""Add English counterparts for Spanish editorial overrides."""

from pathlib import Path


PATH = Path(__file__).resolve().parents[1] / "lib/projects.ts"


def replace_once(text: str, old: str, new: str) -> str:
    if text.count(old) != 1:
        raise RuntimeError(f"Expected one occurrence, found {text.count(old)}")
    return text.replace(old, new)


